/**
 * Tabs. A hardware segmented control: molded segments
 * in a recessed well, a lit cap sliding under the active tab. Composes
 * var(--echo-*). The indicator reads Base UI's --active-tab-* vars.
 */
.echo-tabs__list {
  /* One size scale (sm/md/lg): a tab is as tall as a control of its size. */
  --tab-h: var(--echo-control-default);
  --tab-px: var(--echo-space-6);
  --tab-font: var(--echo-text-sm);
  position: relative;
  display: flex;
  gap: var(--echo-space-2);
  /* A hairline baseline the lit rail rides on. */
  box-shadow: inset 0 -1px 0 var(--echo-seam);
}
.echo-tabs__list[data-size="sm"] {
  --tab-h: var(--echo-control-compact);
  --tab-px: var(--echo-space-4);
  --tab-font: var(--echo-text-xs);
}
.echo-tabs__list[data-size="lg"] {
  --tab-h: var(--echo-control-large);
  --tab-px: var(--echo-space-8);
  --tab-font: var(--echo-text-md);
}

.echo-tabs__tab {
  position: relative;
  z-index: var(--echo-z-raised, 1);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--echo-space-3);
  box-sizing: border-box;
  min-block-size: var(--tab-h);
  border: 0;
  padding-block: 0;
  padding-inline: var(--tab-px);
  border-radius: var(--echo-radius-md) var(--echo-radius-md) 0 0;
  cursor: pointer;
  background: transparent;
  color: var(--echo-text-dim);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--tab-font);
  font-weight: var(--echo-weight-semibold, 600);
  transition:
    color var(--echo-duration-swap) ease,
    background var(--echo-duration-tick) ease;
}

@media (hover: hover) {
  .echo-tabs__tab:hover {
    color: var(--echo-text);
    background: color-mix(in oklab, var(--echo-cap) 30%, transparent);
  }
}

/*
 * Base UI marks the open tab with `data-active`. This rule used to target
 * `[data-selected]`, which Base UI never sets — so the "selected" label was
 * never applied and the open tab stayed at 53% text on a lit primary cap.
 */
.echo-tabs__tab[data-active] {
  color: var(--echo-text);
}

.echo-tabs__tab:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: -2px;
  box-shadow: var(--echo-shadow-ring-inset, inset 0 0 0 2px var(--echo-accent-ink, var(--echo-accent-glow)));
}

/*
 * The open tab is marked by a lit rail under its label — the site's top nav
 * and the install box use the same mark. It used to be a raised primary cap in a
 * well, which made Tabs a copy of Segmented; they are different controls
 * (Tabs switch what you see, Segmented sets a value) and should not look the
 * same. The label stays on the chassis, so its contrast is text-on-surface.
 */
.echo-tabs__indicator {
  position: absolute;
  z-index: var(--echo-z-top, 2);
  bottom: 0;
  left: var(--active-tab-left);
  width: var(--active-tab-width);
  height: 2px;
  border-radius: var(--echo-radius-full);
  /* Emissive: the same lit accent + glow as AppShell's rails. */
  background: var(--echo-accent-glow);
  box-shadow: var(--echo-shadow-glow, 0 0 calc(7px * (1 - var(--echo-drawn, 0))) color-mix(in oklch, var(--echo-accent-glow) 70%, transparent));
  transition:
    left var(--echo-duration-sweep) cubic-bezier(0.2, 0.8, 0.2, 1),
    width var(--echo-duration-sweep) cubic-bezier(0.2, 0.8, 0.2, 1);
}

/*
 * The moving rail (tabs.tsx, echo-ui-core's liquid engine). Once placed it
 * sets data-light on the list and takes over from Base UI's indicator. The
 * glow is a drop shadow on the outer box so it follows the rail's outline.
 */
.echo-tabs__rail {
  position: absolute;
  z-index: var(--echo-z-top, 2);
  bottom: 0;
  height: 2px;
  visibility: hidden;
  pointer-events: none;
  filter: drop-shadow(0 0 3.5px color-mix(in srgb, var(--echo-accent-glow) 70%, transparent));
  will-change: transform, left, width;
}
.echo-tabs__rail-shape {
  position: absolute;
  inset: 0;
  border-radius: var(--echo-radius-full);
  background: var(--echo-accent-glow);
}
.echo-tabs__list[data-light] .echo-tabs__rail {
  visibility: visible;
}
.echo-tabs__list[data-light] .echo-tabs__indicator {
  visibility: hidden;
}
/* Each label is lit by how much of the rail is under it (--on, 0–1). */
.echo-tabs__list[data-light] .echo-tabs__tab {
  color: color-mix(in oklab, var(--echo-text) calc(var(--on, 0) * 100%), var(--echo-text-dim));
  transition: background var(--echo-duration-tick) ease;
}
.echo-tabs__list[data-light] .echo-tabs__tab[data-active] {
  /* The open tab is lit at once; the others brighten as the rail passes. */
  color: var(--echo-text);
}
@media (hover: hover) {
  .echo-tabs__list[data-light] .echo-tabs__tab:hover {
    color: var(--echo-text);
  }
}

.echo-tabs__panel {
  padding: var(--echo-space-9) var(--echo-space-2);
  color: var(--echo-text);
}
.echo-tabs__panel:focus-visible {
  /* The panel takes focus when it has nothing focusable inside, so it needs
     a visible ring like everything else that does. */
  outline: 2px solid var(--echo-accent-ink, var(--echo-accent-glow));
  outline-offset: 2px;
  border-radius: var(--echo-radius-sm);
}

@media (prefers-reduced-motion: reduce) {
  .echo-tabs__indicator {
    transition: none;
  }
}

/* Coarse-pointer target. Touch only. */
@media (pointer: coarse) {
  .echo-tabs__list[data-size="sm"] {
    --tab-h: 44px;
  }
}

/*
 * Forced colors (Windows High Contrast) drops gradients and shadows, which is
 * everything that draws this control's state. System colors draw it instead;
 * nothing here sets forced-color-adjust: none, so focus outlines still show.
 */
@media (forced-colors: active) {
  .echo-tabs__rail {
    display: none;
  }
  .echo-tabs__list[data-light] .echo-tabs__indicator {
    visibility: visible;
  }
  .echo-tabs__list {
    border-bottom: var(--echo-border-hairline, 1px) solid ButtonText;
  }
  .echo-tabs__indicator {
    background: Highlight;
    height: 3px;
  }
  .echo-tabs__tab[data-active],
  .echo-tabs__list[data-light] .echo-tabs__tab[data-active] {
    color: Highlight;
  }
}

"use client";

/**
 * Tabs. Base UI Tabs behavior (roving focus,
 * arrow-key nav, a11y) skinned as a hardware segmented control, with a lit cap
 * that slides under the active tab and sound.select on change.
 *
 * Compound API: <Tabs><Tabs.List><Tabs.Tab/></Tabs.List><Tabs.Panel/></Tabs>.
 * The sliding Indicator is rendered inside Tabs.List automatically.
 *
 * The lit rail is one part that moves (echo-ui-core's liquid engine): it
 * springs to the tab you open, drawing out with speed, leans toward a tab the
 * pointer is over, and each label brightens as the rail slides under it.
 * Base UI's own indicator draws the rail until the moving one is placed, and
 * in forced colors.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import {
  useCallback,
  useLayoutEffect,
  useRef,
  type ComponentProps,
  type PointerEvent,
  type MutableRefObject,
} from "react";
import gsap from "gsap";
import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import { useSoundOptional } from "echo-ui-core/sound";
import { springs } from "echo-ui-core/motion";
import { createLiquid, timing, useReducedMotionRef, type Liquid } from "echo-ui-core/tactile";
import { useControlSize, type ControlSize } from "../size";
import "./tabs.css";

const cx = (...c: (string | undefined)[]) => c.filter(Boolean).join(" ");

/** Narrow Base UI's string-or-function className to a plain string for skinning. */
type Skin<T> = Omit<T, "className"> & { className?: string };

function TabsRoot({ onValueChange, ...props }: ComponentProps<typeof BaseTabs.Root>) {
  const sound = useSoundOptional();
  return (
    <BaseTabs.Root
      onValueChange={(value, eventDetails) => {
        sound?.play("select");
        onValueChange?.(value, eventDetails);
      }}
      {...props}
    />
  );
}

type TabsListProps = Skin<ComponentProps<typeof BaseTabs.List>> & {
  /** How tall each tab is: `sm` 32, `md` 44, `lg` 60px, the control heights. Defaults to the surrounding `SizeProvider`, else `md`. */
  size?: ControlSize;
};

function TabsList({ className, children, ref, size: ownSize, ...props }: TabsListProps) {
  const size = useControlSize(ownSize);
  const reduced = useReducedMotionRef();
  const list = useRef<HTMLDivElement | null>(null);
  const rail = useRef<HTMLSpanElement | null>(null);
  const shape = useRef<HTMLSpanElement | null>(null);
  const liquid = useRef<Liquid | null>(null);

  const setList = useCallback(
    (node: HTMLDivElement | null) => {
      list.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<HTMLDivElement | null>).current = node;
    },
    [ref],
  );

  useLayoutEffect(() => {
    const l = list.current;
    const el = rail.current;
    const sh = shape.current;
    if (!l || !el || !sh) return;
    const tabs = () => [...l.querySelectorAll<HTMLElement>('[role="tab"]')];
    const cap = createLiquid({
      el,
      shape: sh,
      // A 2px rail has no room to taper, so it says speed by drawing out.
      stretch: 0.6,
      restRadius: () => 1,
      onDraw: ({ start, size }) => {
        for (const t of tabs()) {
          const w = t.offsetWidth;
          const covered = Math.max(0, Math.min(start + size, t.offsetLeft + w) - Math.max(start, t.offsetLeft));
          t.style.setProperty("--on", (w ? covered / w : 0).toFixed(3));
        }
      },
    });
    liquid.current = cap;
    let placed = false;
    const place = (animate: boolean) => {
      const t = l.querySelector<HTMLElement>('[role="tab"][data-active]');
      if (!t) return;
      const box = { start: t.offsetLeft, size: t.offsetWidth };
      if (!animate || !placed || reduced.current) {
        cap.place(box, "instant");
        placed = true;
        l.setAttribute("data-light", "");
        return;
      }
      cap.place(box, springs.snappy);
    };
    place(false);
    const changed = new MutationObserver(() => place(true));
    changed.observe(l, { subtree: true, attributes: true, attributeFilter: ["data-active"] });
    const resized = new ResizeObserver(() => place(false));
    resized.observe(l);
    return () => {
      changed.disconnect();
      resized.disconnect();
      cap.destroy();
      liquid.current = null;
      gsap.killTweensOf(el);
    };
  }, [reduced]);

  /* The rail notices the pointer: it leans toward the tab you are over. */
  const lean = (e: PointerEvent<HTMLDivElement>) => {
    const el = rail.current;
    const cap = liquid.current;
    if (!el || !cap || e.pointerType !== "mouse" || reduced.current) return;
    const t = (e.target as Element).closest<HTMLElement>('[role="tab"]');
    const d = t ? t.offsetLeft + t.offsetWidth / 2 - cap.centre : 0;
    gsap.to(el, { ...timing("follow"), overwrite: "auto", x: Math.max(-10, Math.min(10, d * 0.08)) });
  };

  return (
    <BaseTabs.List
      ref={setList}
      className={cx("echo-tabs__list", className)}
      data-size={size}
      onPointerMove={lean}
      onPointerLeave={() => {
        const el = rail.current;
        if (el && !reduced.current) gsap.to(el, { ...timing("rebound"), overwrite: "auto", x: 0 });
      }}
      {...props}
    >
      {children}
      <BaseTabs.Indicator className="echo-tabs__indicator" />
      <span ref={rail} className="echo-tabs__rail" aria-hidden>
        <span ref={shape} className="echo-tabs__rail-shape" />
      </span>
    </BaseTabs.List>
  );
}

function TabsTab({ className, ...props }: Skin<ComponentProps<typeof BaseTabs.Tab>>) {
  return <BaseTabs.Tab className={cx("echo-tabs__tab", className)} {...props} />;
}

function TabsPanel({ className, ...props }: Skin<ComponentProps<typeof BaseTabs.Panel>>) {
  return <BaseTabs.Panel className={cx("echo-tabs__panel", className)} {...props} />;
}

// Assembled into `Tabs` in index.ts, which isn't a client module (BUG-10).
export { TabsRoot, TabsList, TabsTab, TabsPanel };

/**
 * The entry point for Tabs, deliberately NOT a client module: the parts are
 * attached here, from named client exports. Attached inside the "use client"
 * file, they didn't survive a server component's import, so Tabs.List was
 * undefined in a Next.js page or layout and the build failed (BUG-10).
 */
import { TabsRoot, TabsList, TabsTab, TabsPanel } from "./tabs";

export const Tabs = Object.assign(TabsRoot, {
  List: TabsList,
  Tab: TabsTab,
  Panel: TabsPanel,
});
